//! Cargo-driven `cmicontrol.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_WinMainCRTStartup"),
        "x86_64" => ("x86_64-pc-windows-gnu", "WinMainCRTStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "WinMainCRTStartup"),
        o => panic!("cmicontrol-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["import:user32", "import:gdi32", "import:ole32", "import:advapi32", "import:comctl32", "import:shell32", "import:dsound", "import:setupapi", "import:winmm", "import:msvcrt", "import:kernel32", "body", "import:ntdll", "engine:oldnames"],
        "x86_64" => &["import:user32", "import:gdi32", "import:ole32", "import:advapi32", "import:comctl32", "import:shell32", "import:dsound", "import:setupapi", "import:winmm", "import:msvcrt", "import:kernel32", "body", "import:ntdll", "engine:oldnames"],
        "aarch64" => &["import:user32", "import:gdi32", "import:ole32", "import:advapi32", "import:comctl32", "import:shell32", "import:dsound", "import:setupapi", "import:winmm", "import:msvcrt", "import:kernel32", "body", "import:ntdll", "engine:oldnames"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/drivers/wdm/audio/drivers/CMIDriver/cmicontrol",
        "vendor/cmidriver/cmicontrol",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "vendor/cmidriver/cmicontrol/..",
        "sdk/lib/pseh/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
    ];

    Linker::new(target_json)
        .c_from_compile_db("cmicontrol_shims", &["vendor/cmidriver/cmicontrol/main.cpp"])
        .rc("vendor/cmidriver/cmicontrol/window.rc", rc_includes, rc_flags, rc_defines)
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/comctl32/comctl32.spec", "comctl32.dll", "comctl32")
        .import_lib("dll/win32/shell32/shell32.spec", "shell32.dll", "shell32")
        .import_lib("dll/directx/wine/dsound/dsound.spec", "dsound.dll", "dsound")
        .import_lib("dll/win32/setupapi/setupapi.spec", "setupapi.dll", "setupapi")
        .import_lib("dll/win32/winmm/winmm.spec", "winmm.dll", "winmm")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::ExeAnsi)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "windows:5.01".into(),
        });
}
